    SELECT
        'SCDE'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(SCHEDULE_NO), LENGTH('SCDE' ) + 1)), 0) + 1, 6, '0')
    FROM SCHEDULE

INSERT INTO SCHEDULE (
SCHEDULE_NO
	, USER_ID
	, SCHEDULE_NAME
	, SCHEDULE_CONTENT
	, SCHEDULE_START_DATE
	, SCHEDULE_END_DATE
) VALUES (
	#{scheduleNo}
	, #{userId}
	, #{scheduleName}
	, #{scheduleContent}
	, #{scheduleStartDate}
	, #{scheduleEndDate}
)

