UPDATE SCHEDULE
	SET 
		SCHEDULE_NAME = #{scheduleName}
		, SCHEDULE_START_DATE = #{scheduleStartTimestamp}
		, SCHEDULE_END_DATE = #{scheduleEndTimestamp}
	WHERE SCHEDULE_NO = #{scheduleNo}
